import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from 'react-router-dom';
import "./RiverDashboard.css"; // Reuse your existing styles

const FloodMap = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [floodData, setFloodData] = useState(null);
  
  // Update this URL to match your backend
  const API_URL = "http://localhost:8000/api/flood-analysis"; 

  useEffect(() => {
    const fetchFloodData = async () => {
      try {
        const response = await axios.get(API_URL);
        if (response.data.status === "success") {
          setFloodData(response.data);
        }
      } catch (error) {
        console.error("Error fetching flood data:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchFloodData();
  }, []);

  if (loading) return <div className="rd-loading"><div className="rd-spinner"></div><p>Analyzing Satellite Terrain Data...</p></div>;

  return (
    <div className="rd-container">
      {/* --- Top Nav --- */}
      <nav className="rd-nav-overlay">
        <div className="rd-wrapper rd-flex-between">
            <div className="rd-brand"><i className="fas fa-water"></i> Periyar<span>Watch</span></div>
            <div className="rd-links">
              <button onClick={() => navigate('/')}>Home</button>
              <button onClick={() => navigate('/dashboard')}>Dashboard</button>
              <button className="active">Flood Analysis</button>
            </div>
        </div>
      </nav>

      <main className="rd-main-content rd-wrapper">
        
        {/* --- Header Section --- */}
        <div className="rd-hero-text" style={{marginTop: '80px', textAlign: 'center'}}>
          <span className="rd-pill"><i className="fas fa-satellite"></i> Real-Time Terrain Analysis</span>
          <h1>Flood Impact Detection</h1>
          <p>Comparing live river levels against Digital Elevation Model (DEM)</p>
        </div>

        {/* --- Summary Cards --- */}
        <div className="rd-stats-grid">
            <div className="rd-card glass">
                <div className="card-head"><span>Current River Level</span><i className="fas fa-ruler-vertical"></i></div>
                <div className="big-stat">{floodData?.current_water_level} <small>m</small></div>
            </div>
            <div className="rd-card glass">
                <div className="card-head"><span>Flooded Zones Identified</span><i className="fas fa-map-marker-alt"></i></div>
                <div className="big-stat" style={{color: '#ef4444'}}>{floodData?.flooded_count} <small>points</small></div>
            </div>
            <div className="rd-card glass">
                <div className="card-head"><span>Risk Status</span><i className="fas fa-shield-alt"></i></div>
                <div className="big-stat" style={{color: floodData?.flooded_count > 0 ? '#ef4444' : '#10b981'}}>
                    {floodData?.flooded_count > 0 ? "High Alert" : "Safe"}
                </div>
            </div>
        </div>

        {/* --- Detailed List Section --- */}
        <section className="rd-section glass" style={{marginTop: '30px'}}>
            <div className="sec-header">
                <h3><i className="fas fa-list-ul"></i> Impacted Locations (Sample Data)</h3>
            </div>
            
            <div className="rd-table-container">
                <table style={{width: '100%', borderCollapse: 'collapse', color: 'white'}}>
                    <thead>
                        <tr style={{borderBottom: '1px solid rgba(255,255,255,0.2)', textAlign: 'left'}}>
                            <th style={{padding: '12px'}}>Coordinates (Lat, Lon)</th>
                            <th style={{padding: '12px'}}>Ground Elev.</th>
                            <th style={{padding: '12px'}}>Flood Depth</th>
                            <th style={{padding: '12px'}}>Impact Analysis</th>
                            <th style={{padding: '12px'}}>Severity</th>
                        </tr>
                    </thead>
                    <tbody>
                        {floodData?.data.map((item, index) => (
                            <tr key={index} style={{borderBottom: '1px solid rgba(255,255,255,0.05)'}}>
                                <td style={{padding: '12px', fontFamily: 'monospace'}}>{item.lat}, {item.lon}</td>
                                <td style={{padding: '12px'}}>{item.ground_elevation} m</td>
                                <td style={{padding: '12px', color: '#60a5fa', fontWeight: 'bold'}}>+{item.flood_depth} m</td>
                                <td style={{padding: '12px'}}>{item.explanation}</td>
                                <td style={{padding: '12px'}}>
                                    <span className={`status-badge ${item.status === 'Critical' ? 'status-critical' : 'status-caution'}`}>
                                        {item.status}
                                    </span>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
                {floodData?.data.length === 0 && <p style={{padding: '20px', textAlign: 'center'}}>No flood risks detected at current water levels.</p>}
            </div>
        </section>

      </main>
    </div>
  );
};

export default FloodMap;
